namespace MUnique.OpenMU.Persistence.Initialization.VersionSeasonSix.Season21;

/// <summary>
/// The skill data of Season 21 (<c>Resources/Season21/Skills.json</c>, generated by <c>Generator/season21-skills.mjs</c>).
/// </summary>
internal sealed class Season21SkillData
{
    /// <summary>
    /// Gets the formulas of the tree nodes by id (variable <c>level</c>).
    /// </summary>
    public Dictionary<short, string> Formulas { get; init; } = [];

    /// <summary>
    /// Gets the skills.
    /// </summary>
    public List<Season21SkillRow> Skills { get; init; } = [];

    /// <summary>
    /// Gets the master tree nodes.
    /// </summary>
    public List<Season21MasterNodeRow> MasterNodes { get; init; } = [];

    /// <summary>
    /// Gets the skill enhancement tree nodes.
    /// </summary>
    public List<Season21EnhanceNodeRow> EnhanceNodes { get; init; } = [];

    /// <summary>
    /// Gets the passives of the skill enhancement tree.
    /// </summary>
    public List<Season21EnhancePassiveRow> EnhancePassives { get; init; } = [];

    /// <summary>
    /// Gets the debuff fields.
    /// </summary>
    public List<Season21MagicFieldRow> MagicFields { get; init; } = [];

    /// <summary>
    /// Gets the effects.
    /// </summary>
    public List<Season21EffectRow> Effects { get; init; } = [];

    /// <summary>
    /// Gets the skills of new characters.
    /// </summary>
    public List<Season21StartSkillRow> StartSkills { get; init; } = [];

    /// <summary>
    /// Gets the books.
    /// </summary>
    public List<Season21SkillBookRow> Books { get; init; } = [];
}
